using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Textures;
namespace ToneCustoms.ShellStudio.Validation;
public enum ValidationSeverity { Info, Warning, Error }
public sealed record ValidationIssue(ValidationSeverity Severity,string Area,string Message,Guid? ObjectId=null);
public sealed class ProjectValidator { public IReadOnlyList<ValidationIssue> Validate(ShellProject p){var r=new List<ValidationIssue>();if(p.Objects.Count==0)r.Add(new(ValidationSeverity.Warning,"Geometry","Project contains no geometry"));foreach(var o in p.Objects){if(o.Scale.X<=0||o.Scale.Y<=0||o.Scale.Z<=0)r.Add(new(ValidationSeverity.Error,"Geometry",$"{o.Name} has invalid scale",o.Id));if(string.IsNullOrWhiteSpace(o.MaterialId)&&o.Type is not SceneObjectType.Light)r.Add(new(ValidationSeverity.Warning,"Materials",$"{o.Name} has no material",o.Id));if(o.Type==SceneObjectType.Prop&&string.IsNullOrWhiteSpace(o.ModelName)&&string.IsNullOrWhiteSpace(o.SourcePath))r.Add(new(ValidationSeverity.Warning,"Props",$"{o.Name} has no model source",o.Id));}var dds=new DdsService();foreach(var m in p.Materials)foreach(var path in new[]{m.DiffuseDds,m.NormalDds,m.SpecularDds}.Where(x=>!string.IsNullOrWhiteSpace(x))){if(!File.Exists(path)){r.Add(new(ValidationSeverity.Error,"Textures",$"Missing DDS: {path}"));continue;}foreach(var x in dds.Validate(dds.Inspect(path!)))r.Add(new(ValidationSeverity.Warning,"Textures",$"{m.Name}: {x}"));}foreach(var opening in p.WallOpenings)if(!p.Objects.Any(x=>x.Id==opening.WallId&&x.Type==SceneObjectType.Wall))r.Add(new(ValidationSeverity.Error,"Openings","Wall opening references a missing wall"));return r;}public void AutoFixSafe(ShellProject p){foreach(var o in p.Objects)o.Scale=new(Math.Max(.01f,o.Scale.X),Math.Max(.01f,o.Scale.Y),Math.Max(.01f,o.Scale.Z));p.WallOpenings.RemoveAll(x=>!p.Objects.Any(o=>o.Id==x.WallId));} }
